using Microsoft.AspNetCore.Http.Json;
using Microsoft.AspNetCore.Identity;
using Microsoft.OpenApi.Models;
using RaceDay.Api;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddSingleton<InMemoryStore>();
builder.Services.AddDistributedMemoryCache();
builder.Services.AddSession(options => { options.Cookie.Name = ".RaceDay.Session"; options.Cookie.HttpOnly = true; options.Cookie.IsEssential = true; options.IdleTimeout = TimeSpan.FromMinutes(30); });
builder.Services.Configure<JsonOptions>(options => options.SerializerOptions.PropertyNameCaseInsensitive = true);
builder.Services.AddEndpointsApiExplorer();
builder.Services.AddSwaggerGen(c => { c.SwaggerDoc("v1", new OpenApiInfo { Title = "RaceDay API", Version = "v1", Description = "Database-free REST API prototype. Session authentication; in-memory data resets when the process stops." }); });
var app = builder.Build();
app.UseSwagger(); app.UseSwaggerUI(); app.UseSession();
app.MapGet("/", () => Results.Redirect("/swagger")).WithSummary("Open Swagger UI").WithDescription("Redirects to the interactive API documentation.");

Guid? UserId(HttpContext c) => Guid.TryParse(c.Session.GetString("UserId"), out var id) ? id : null;
string? Role(HttpContext c) => c.Session.GetString("Role");
bool HasRole(HttpContext c, string role) => UserId(c) is not null && Role(c) == role;
IResult UnauthorizedResult() => Results.Json(new { error = "Please log in to access this endpoint." }, statusCode: 401);
IResult ForbiddenResult() => Results.Json(new { error = "Your account role cannot access this endpoint." }, statusCode: 403);

var auth = app.MapGroup("/api/auth").WithTags("Authentication");
auth.MapPost("/register", (RegisterRequest request, InMemoryStore store) => {
    if (string.IsNullOrWhiteSpace(request.FullName) || string.IsNullOrWhiteSpace(request.Email) || string.IsNullOrWhiteSpace(request.Password)) return Results.BadRequest(new { error = "Full name, email and password are required." });
    if (request.Password.Length < 8) return Results.BadRequest(new { error = "Password must contain at least 8 characters." });
    var role = request.Role?.Trim(); if (role is not (Roles.Organiser or Roles.Participant)) return Results.BadRequest(new { error = "Role must be Organiser or Participant." });
    if (store.FindByEmail(request.Email) is not null) return Results.Conflict(new { error = "An account with this email already exists." });
    var user = new User { FullName = request.FullName.Trim(), Email = request.Email.Trim(), Role = role! };
    user.PasswordHash = store.Hasher.HashPassword(user, request.Password); store.Users[user.Id] = user;
    return Results.Created($"/api/profile", new { user.Id, user.FullName, user.Email, user.Role });
}).WithSummary("Register an account").WithDescription("Creates an Organiser or Participant account. Passwords are securely hashed; plaintext passwords are never stored.").Produces(201).Produces(400).Produces(409);
auth.MapPost("/login", (LoginRequest request, HttpContext context, InMemoryStore store) => {
    var user = store.FindByEmail(request.Email ?? ""); if (user is null || store.Hasher.VerifyHashedPassword(user, user.PasswordHash, request.Password ?? "") == PasswordVerificationResult.Failed) return Results.Json(new { error = "Invalid email or password." }, statusCode: 401);
    context.Session.SetString("UserId", user.Id.ToString()); context.Session.SetString("Role", user.Role); context.Session.SetString("FullName", user.FullName);
    return Results.Ok(new { message = "Login successful", user.Id, user.FullName, user.Email, user.Role, sessionExpiresInMinutes = 30 });
}).WithSummary("Log in and create a session").WithDescription("Valid credentials create a server-side session containing the user ID and role.").Produces(200).Produces(401);
auth.MapPost("/logout", (HttpContext context) => { context.Session.Clear(); return Results.Ok(new { message = "Logged out." }); }).WithSummary("Log out").WithDescription("Clears the current session.");
auth.MapGet("/me", (HttpContext context, InMemoryStore store) => { var id = UserId(context); if (id is null) return UnauthorizedResult(); var u = store.Users.GetValueOrDefault(id.Value); return u is null ? UnauthorizedResult() : Results.Ok(new { u.Id, u.FullName, u.Email, u.Role }); }).WithSummary("Get the logged-in account").WithDescription("Returns the current session's user profile.");

var profile = app.MapGroup("/api/profile").WithTags("Profile");
profile.MapGet("", (HttpContext c, InMemoryStore s) => { var id = UserId(c); if (id is null) return UnauthorizedResult(); var u = s.Users.GetValueOrDefault(id.Value); if (u is null) return UnauthorizedResult(); return Results.Ok(new { u.Id, u.FullName, u.Email, u.Role }); }).WithSummary("View own profile").WithDescription("Both roles can view their own profile; requires login.");
profile.MapPut("", (ProfileUpdateRequest request, HttpContext c, InMemoryStore s) => { var id = UserId(c); if (id is null) return UnauthorizedResult(); var u = s.Users.GetValueOrDefault(id.Value); if (u is null) return UnauthorizedResult(); if (string.IsNullOrWhiteSpace(request.FullName) || string.IsNullOrWhiteSpace(request.Email)) return Results.BadRequest(new { error = "Name and email are required." }); var duplicate = s.FindByEmail(request.Email); if (duplicate is not null && duplicate.Id != u.Id) return Results.Conflict(new { error = "Email is already in use." }); u.FullName = request.FullName.Trim(); u.Email = request.Email.Trim(); return Results.Ok(new { u.Id, u.FullName, u.Email, u.Role }); }).WithSummary("Update own profile").WithDescription("Updates the logged-in user's name and email; role cannot be changed here.");

var events = app.MapGroup("/api/events").WithTags("Events");
events.MapGet("", (InMemoryStore s) => Results.Ok(s.Events.Values.OrderBy(e => e.Date))).WithSummary("List events").WithDescription("Public endpoint listing all events.");
events.MapGet("/{id:guid}", (Guid id, InMemoryStore s) => { if (s.Events.TryGetValue(id, out var e)) return Results.Ok(e); return Results.NotFound(new { error = "Event not found." }); }).WithSummary("Get an event").WithDescription("Returns one event by ID.");
events.MapPost("", (EventRequest r, HttpContext c, InMemoryStore s) => { var uid = UserId(c); if (uid is null) return UnauthorizedResult(); if (!HasRole(c, Roles.Organiser)) return ForbiddenResult(); if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Location) || r.DistanceKm <= 0 || !new[]{"run","walk","cycle"}.Contains(r.EventType?.ToLowerInvariant())) return Results.BadRequest(new { error = "Name, location, positive distance and event type Run/Walk/Cycle are required." }); var e = new RaceEvent { OrganiserId = uid.Value, Name = r.Name.Trim(), Description = r.Description ?? "", Date = r.Date, Location = r.Location.Trim(), DistanceKm = r.DistanceKm, EventType = char.ToUpperInvariant(r.EventType[0]) + r.EventType[1..].ToLowerInvariant() }; s.Events[e.Id] = e; return Results.Created($"/api/events/{e.Id}", e); }).WithSummary("Create an event (Organiser)").WithDescription("Only logged-in Organisers may create events.");
events.MapPut("/{id:guid}", (Guid id, EventRequest r, HttpContext c, InMemoryStore s) => { var uid = UserId(c); if (uid is null) return UnauthorizedResult(); if (!HasRole(c, Roles.Organiser)) return ForbiddenResult(); if (!s.Events.TryGetValue(id, out var e)) return Results.NotFound(); if (e.OrganiserId != uid.Value) return ForbiddenResult(); if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Location) || r.DistanceKm <= 0 || !new[]{"run","walk","cycle"}.Contains(r.EventType?.ToLowerInvariant())) return Results.BadRequest(new { error = "Valid event details are required." }); e.Name=r.Name.Trim(); e.Description=r.Description ?? ""; e.Date=r.Date; e.Location=r.Location.Trim(); e.DistanceKm=r.DistanceKm; e.EventType=char.ToUpperInvariant(r.EventType[0])+r.EventType[1..].ToLowerInvariant(); return Results.Ok(e); }).WithSummary("Update an event (owner Organiser)").WithDescription("Only the Organiser who created the event may update it.");
events.MapDelete("/{id:guid}", (Guid id, HttpContext c, InMemoryStore s) => { var uid = UserId(c); if (uid is null) return UnauthorizedResult(); if (!HasRole(c, Roles.Organiser)) return ForbiddenResult(); if (!s.Events.TryGetValue(id, out var e)) return Results.NotFound(); if (e.OrganiserId != uid.Value) return ForbiddenResult(); s.Events.TryRemove(id, out _); foreach (var cat in s.Categories.Values.Where(x=>x.EventId==id)) s.Categories.TryRemove(cat.Id,out _); foreach (var en in s.Enrolments.Values.Where(x=>x.EventId==id)) { s.Enrolments.TryRemove(en.Id,out _); foreach(var result in s.Results.Values.Where(x=>x.EnrolmentId==en.Id)) s.Results.TryRemove(result.Id,out _); } return Results.NoContent(); }).WithSummary("Delete an event (owner Organiser)").WithDescription("Deletes the event and its associated categories, enrolments and results.");

var cats = app.MapGroup("/api/events/{eventId:guid}/categories").WithTags("Categories");
cats.MapGet("", (Guid eventId, InMemoryStore s) => !s.Events.ContainsKey(eventId) ? Results.NotFound(new { error="Event not found." }) : Results.Ok(s.Categories.Values.Where(x=>x.EventId==eventId))).WithSummary("List event categories").WithDescription("Both roles and unauthenticated users may view categories for an event.");
cats.MapPost("", (Guid eventId, CategoryRequest r, HttpContext c, InMemoryStore s) => { var uid=UserId(c); if(uid is null)return UnauthorizedResult(); if(!HasRole(c,Roles.Organiser))return ForbiddenResult(); if(!s.Events.TryGetValue(eventId,out var e))return Results.NotFound(new{error="Event not found."}); if(e.OrganiserId!=uid.Value)return ForbiddenResult(); if(string.IsNullOrWhiteSpace(r.Name)||string.IsNullOrWhiteSpace(r.CategoryType))return Results.BadRequest(new{error="Name and category type are required."}); var cat=new EventCategory{EventId=eventId,Name=r.Name.Trim(),CategoryType=r.CategoryType.Trim()}; s.Categories[cat.Id]=cat; return Results.Created($"/api/events/{eventId}/categories",cat); }).WithSummary("Create a category (Organiser)").WithDescription("Creates an age or distance category for an event owned by the logged-in Organiser.");
cats.MapPut("/{categoryId:guid}", (Guid eventId, Guid categoryId, CategoryRequest r, HttpContext c, InMemoryStore s) => { var uid=UserId(c); if(uid is null)return UnauthorizedResult(); if(!HasRole(c,Roles.Organiser))return ForbiddenResult(); if(!s.Events.TryGetValue(eventId,out var e))return Results.NotFound(); if(e.OrganiserId!=uid.Value)return ForbiddenResult(); if(!s.Categories.TryGetValue(categoryId,out var cat)||cat.EventId!=eventId)return Results.NotFound(); if(string.IsNullOrWhiteSpace(r.Name)||string.IsNullOrWhiteSpace(r.CategoryType))return Results.BadRequest(); cat.Name=r.Name.Trim();cat.CategoryType=r.CategoryType.Trim();return Results.Ok(cat); }).WithSummary("Update a category (Organiser)").WithDescription("Updates a category for an event owned by the logged-in Organiser.");
cats.MapDelete("/{categoryId:guid}", (Guid eventId, Guid categoryId, HttpContext c, InMemoryStore s) => { var uid=UserId(c); if(uid is null)return UnauthorizedResult();if(!HasRole(c,Roles.Organiser))return ForbiddenResult();if(!s.Events.TryGetValue(eventId,out var e))return Results.NotFound();if(e.OrganiserId!=uid.Value)return ForbiddenResult();if(!s.Categories.TryGetValue(categoryId,out var cat)||cat.EventId!=eventId)return Results.NotFound();if(s.Enrolments.Values.Any(x=>x.CategoryId==categoryId))return Results.Conflict(new{error="Cannot delete a category already used by an enrolment."});s.Categories.TryRemove(categoryId,out _);return Results.NoContent(); }).WithSummary("Delete a category (Organiser)").WithDescription("Deletes a category if it has no enrolments.");

var enrol = app.MapGroup("/api/enrolments").WithTags("Enrolments");
enrol.MapPost("", (EnrolmentRequest r,HttpContext c,InMemoryStore s)=>{var uid=UserId(c);if(uid is null)return UnauthorizedResult();if(!HasRole(c,Roles.Participant))return ForbiddenResult();if(!s.Events.ContainsKey(r.EventId))return Results.NotFound(new{error="Event not found."});if(!s.Categories.TryGetValue(r.CategoryId,out var cat)||cat.EventId!=r.EventId)return Results.BadRequest(new{error="Category must belong to the selected event."});if(s.Enrolments.Values.Any(x=>x.ParticipantId==uid.Value&&x.EventId==r.EventId))return Results.Conflict(new{error="You are already enrolled in this event."});var en=new Enrolment{ParticipantId=uid.Value,EventId=r.EventId,CategoryId=r.CategoryId};s.Enrolments[en.Id]=en;return Results.Created($"/api/enrolments/{en.Id}",en);}).WithSummary("Enrol in an event (Participant)").WithDescription("A Participant selects an event and a category belonging to that event. Duplicate enrolment is prevented.");
enrol.MapGet("/mine",(HttpContext c,InMemoryStore s)=>{var uid=UserId(c);if(uid is null)return UnauthorizedResult();if(!HasRole(c,Roles.Participant))return ForbiddenResult();return Results.Ok(s.Enrolments.Values.Where(x=>x.ParticipantId==uid.Value));}).WithSummary("View my enrolments (Participant)").WithDescription("Returns only the logged-in Participant's enrolments.");
enrol.MapGet("/event/{eventId:guid}",(Guid eventId,HttpContext c,InMemoryStore s)=>{var uid=UserId(c);if(uid is null)return UnauthorizedResult();if(!HasRole(c,Roles.Organiser))return ForbiddenResult();if(!s.Events.TryGetValue(eventId,out var e))return Results.NotFound();if(e.OrganiserId!=uid.Value)return ForbiddenResult();return Results.Ok(s.Enrolments.Values.Where(x=>x.EventId==eventId));}).WithSummary("View event enrolments (Organiser)").WithDescription("Only the event's owning Organiser can view its enrolments.");

var results = app.MapGroup("/api/results").WithTags("Results");
results.MapGet("/mine",(HttpContext c,InMemoryStore s)=>{var uid=UserId(c);if(uid is null)return UnauthorizedResult();if(!HasRole(c,Roles.Participant))return ForbiddenResult();var myEnrolments=s.Enrolments.Values.Where(x=>x.ParticipantId==uid.Value).Select(x=>x.Id).ToHashSet();return Results.Ok(s.Results.Values.Where(x=>myEnrolments.Contains(x.EnrolmentId)));}).WithSummary("View my results (Participant)").WithDescription("Returns results linked to the logged-in Participant's enrolments.");
results.MapPost("",(ResultRequest r,HttpContext c,InMemoryStore s)=>{var uid=UserId(c);if(uid is null)return UnauthorizedResult();if(!HasRole(c,Roles.Organiser))return ForbiddenResult();if(r.Position<1||r.FinishTime<=TimeSpan.Zero)return Results.BadRequest(new{error="Position must be positive and finish time must be greater than zero."});if(!s.Enrolments.TryGetValue(r.EnrolmentId,out var en))return Results.NotFound(new{error="Enrolment not found."});if(!s.Events.TryGetValue(en.EventId,out var e))return Results.NotFound();if(e.OrganiserId!=uid.Value)return ForbiddenResult();var existing=s.Results.Values.FirstOrDefault(x=>x.EnrolmentId==r.EnrolmentId);if(existing is not null){existing.FinishTime=r.FinishTime;existing.Position=r.Position;return Results.Ok(existing);}var result=new RaceResult{EnrolmentId=r.EnrolmentId,FinishTime=r.FinishTime,Position=r.Position};s.Results[result.Id]=result;return Results.Created($"/api/results/{result.Id}",result);}).WithSummary("Capture a result (Organiser)").WithDescription("The owning Organiser records or updates a Participant's finish time and finishing position.");

app.Run();
public partial class Program { }
